import type { FC } from 'react';
import { QR_PRESETS, type QrPreset, type QrStyleState } from '@/lib/qr/style';

interface QuickStylesProps {
  style: QrStyleState;
  onApply: (preset: QrPreset) => void;
}

// Not a separate piece of state — a preset reads as "active" for as long as
// the current style values still match it exactly. Tweaking any field in the
// Colours/Shapes panels afterwards naturally un-highlights it.
function matchesPreset(style: QrStyleState, preset: QrPreset): boolean {
  return (
    style.dotsType === preset.dotsType &&
    style.cornersSquareType === preset.cornersSquareType &&
    style.cornersDotType === preset.cornersDotType &&
    style.fgColor.toLowerCase() === preset.fgColor.toLowerCase() &&
    style.bgColor.toLowerCase() === preset.bgColor.toLowerCase()
  );
}

const QuickStyles: FC<QuickStylesProps> = ({ style, onApply }) => {
  return (
    <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="Quick style presets">
      {QR_PRESETS.map((preset) => {
        const isActive = matchesPreset(style, preset);
        return (
          <button
            key={preset.label}
            type="button"
            role="radio"
            aria-checked={isActive}
            onClick={() => onApply(preset)}
            className={`px-3.5 py-1.5 rounded-full text-sm font-medium border transition-colors ${
              isActive
                ? 'bg-accent text-accent-foreground border-accent'
                : 'bg-background/40 text-foreground/70 border-border hover:text-foreground hover:border-accent/40'
            }`}
          >
            {preset.label}
          </button>
        );
      })}
    </div>
  );
};

export default QuickStyles;
