import type { FC } from 'react';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import type { QrContentType, QrFieldsMap } from '@/lib/qr/types';
import PillGroup from '@/components/tools/PillGroup';

interface ContentFormProps {
  type: QrContentType;
  value: QrFieldsMap[QrContentType];
  onChange: (patch: Partial<QrFieldsMap[QrContentType]>) => void;
}

const fieldLabelClass = 'block text-xs font-medium text-muted-foreground mb-1.5';

const ContentForm: FC<ContentFormProps> = ({ type, value, onChange }) => {
  switch (type) {
    case 'url': {
      const v = value as QrFieldsMap['url'];
      return (
        <div>
          <label className={fieldLabelClass}>URL</label>
          <Input
            type="text"
            value={v.url}
            onChange={(e) => onChange({ url: e.target.value })}
            placeholder="https://example.com"
            spellCheck={false}
          />
        </div>
      );
    }

    case 'text': {
      const v = value as QrFieldsMap['text'];
      return (
        <div>
          <label className={fieldLabelClass}>Text</label>
          <Textarea
            value={v.text}
            onChange={(e) => onChange({ text: e.target.value })}
            placeholder="Any text to encode"
            rows={4}
          />
        </div>
      );
    }

    case 'email': {
      const v = value as QrFieldsMap['email'];
      return (
        <div className="space-y-4">
          <div>
            <label className={fieldLabelClass}>To</label>
            <Input
              type="email"
              value={v.to}
              onChange={(e) => onChange({ to: e.target.value })}
              placeholder="name@example.com"
            />
          </div>
          <div>
            <label className={fieldLabelClass}>Subject (optional)</label>
            <Input
              type="text"
              value={v.subject}
              onChange={(e) => onChange({ subject: e.target.value })}
              placeholder="Subject"
            />
          </div>
          <div>
            <label className={fieldLabelClass}>Body (optional)</label>
            <Textarea
              value={v.body}
              onChange={(e) => onChange({ body: e.target.value })}
              placeholder="Message body"
              rows={3}
            />
          </div>
        </div>
      );
    }

    case 'phone': {
      const v = value as QrFieldsMap['phone'];
      return (
        <div>
          <label className={fieldLabelClass}>Phone number</label>
          <Input
            type="tel"
            value={v.phone}
            onChange={(e) => onChange({ phone: e.target.value })}
            placeholder="+1 555 555 5555"
          />
        </div>
      );
    }

    case 'sms': {
      const v = value as QrFieldsMap['sms'];
      return (
        <div className="space-y-4">
          <div>
            <label className={fieldLabelClass}>Phone number</label>
            <Input
              type="tel"
              value={v.phone}
              onChange={(e) => onChange({ phone: e.target.value })}
              placeholder="+1 555 555 5555"
            />
          </div>
          <div>
            <label className={fieldLabelClass}>Message (optional)</label>
            <Textarea
              value={v.message}
              onChange={(e) => onChange({ message: e.target.value })}
              placeholder="Pre-filled message"
              rows={3}
            />
          </div>
        </div>
      );
    }

    case 'wifi': {
      const v = value as QrFieldsMap['wifi'];
      return (
        <div className="space-y-4">
          <div>
            <label className={fieldLabelClass}>Network name (SSID)</label>
            <Input
              type="text"
              value={v.ssid}
              onChange={(e) => onChange({ ssid: e.target.value })}
              placeholder="My WiFi"
            />
          </div>
          <div>
            <label className={fieldLabelClass}>Security</label>
            <PillGroup
              aria-label="WiFi security type"
              value={v.encryption}
              onChange={(encryption) => onChange({ encryption })}
              options={[
                { value: 'WPA', label: 'WPA/WPA2' },
                { value: 'WEP', label: 'WEP' },
                { value: 'nopass', label: 'None' },
              ]}
            />
          </div>
          {v.encryption !== 'nopass' && (
            <div>
              <label className={fieldLabelClass}>Password</label>
              <Input
                type="text"
                value={v.password}
                onChange={(e) => onChange({ password: e.target.value })}
                placeholder="WiFi password"
              />
            </div>
          )}
          <div className="flex items-center justify-between">
            <label className="text-sm text-foreground/80">Hidden network</label>
            <Switch checked={v.hidden} onCheckedChange={(hidden) => onChange({ hidden })} />
          </div>
        </div>
      );
    }

    case 'geo': {
      const v = value as QrFieldsMap['geo'];
      return (
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className={fieldLabelClass}>Latitude</label>
            <Input
              type="text"
              inputMode="decimal"
              value={v.lat}
              onChange={(e) => onChange({ lat: e.target.value })}
              placeholder="37.7749"
            />
          </div>
          <div>
            <label className={fieldLabelClass}>Longitude</label>
            <Input
              type="text"
              inputMode="decimal"
              value={v.lng}
              onChange={(e) => onChange({ lng: e.target.value })}
              placeholder="-122.4194"
            />
          </div>
        </div>
      );
    }

    default:
      return null;
  }
};

export default ContentForm;
